                        break
                nums = re.findall(r'\d+', low)
                if mon:
                    yr = [int(x) for x in nums if len(x) == 4]
                    dy = [int(x) for x in nums if len(x) <= 2]
                    if yr and dy:
                        out = (yr[0], mon, dy[0])
